-- Gate 25 (Dakara E1, world 61). The row itself is ORIGINAL_DATA: it equals
-- the client's CookedDataStargates entry 25 field for field, and it is the
-- gate prefab's origin on top of the gate dais.
--
-- The arrival pin is PROJECT_FINAL_RECONSTRUCTION (Dakara rebuild DK-01),
-- placement class MAP-GEOMETRY on an AUTHORED axis, confidence MEDIUM until
-- a client has walked it: (96.87, -16.75, 243.23), yaw 3.072.
--
--   * Where: on the gate's own facing axis (the row's yaw 3.072 is
--     (0.07, -1.00), -Z, out of the gate and down the plaza), 10.0 m in
--     front of the row. The 10 m is this project's choice.
--   * Floor: `obj_slab` over the cooked chunk 00020000 (`extract_map`) shows
--     the dais top at y -15.21 under the gate, a flight of shallow steps
--     (treads tilted 9.3 degrees) down from about z 251 to its foot at
--     z 246.1, and one flat slab at y -16.80 from there on (x 86 to 108,
--     z 232 to 260). The pin is 2.9 m past the foot of the steps, 0.05 m
--     above the slab, with nothing but floor in a 3 m box and 8 m of clear
--     line along the axis. The DHD (spawn 38) is 6.0 m further on.
--   * Navmesh: dakara_e1.nav component 279, the component of the gate row,
--     the DHD and the plaza start point (100, -17.4, 230) of Class Start
--     v6's respawner 610.
--   * Why pinned at all: the row is inside the gate's own volume (point set
--     1005 `Dakara_E1.Stargate`, radius 2.5), so an unpinned traveller
--     arrives inside the volume that is crossed to leave. That is inert on
--     the server today (the dial is per entity and no chain is keyed on the
--     region; see the Harset row above), and nobody has seen what a client
--     does there. The pin puts the arrival 10.5 m from the volume's axis,
--     facing away from the gate, as the Debug Area row does. World 61 is
--     `navmesh_mode = 'advisory'`, so the server accepts the pin as written.
--   * `.gotolocation Dakara_E1` with no coordinates uses this point too.
--
-- Guard: `gate_dakara_e1_tests.rs` in cimmeria-cell-world. To correct the pin
-- after a playtest, edit the four arrival_* values here and the constant
-- there.
INSERT INTO stargates (address1, address2, address3, address4, address5, address6, address_origin, stargate_id, name, pitch, prefab_sequence, roll, world_id, x_pos, y_pos, yaw, z_pos, event_set_id, arrival_x, arrival_y, arrival_z, arrival_yaw) VALUES (8, 36, 31, 17, 4, 10, 13, 25, 'Dakara E1', 0, 'Dakara_E1.Main_Sequence.Prefabs.GLB-Stargate_Prefab_Seq', 0, 61, 96.174003999999996, -15.164, 3.0720000000000001, 253.205994, 10013, 96.87, -16.75, 243.23, 3.072);

-- Gate 15 (Agnos): the recovered row is all zeros, and the cooked Agnos map
-- has no stargate prefab to recover it from, so gate travel and a
-- no-coordinates `.gotolocation Agnos` landed at the world origin, ~34 m
-- under the floor with nothing within 4 m. The arrival is pinned to the
-- map's only authored arrival, its PlayerStart: UE3 Location converted with
-- `ue3_to_bw` (BigWorld = (UE.y, UE.z, UE.x) / 100) to (20.640, 34.939,
-- 15.890), yaw 0, on the Ancient platform deck (agnos.nav component 2513,
-- 1,536 m^2). Evidence class: MAP ACTOR, provisional until a playtest
-- (2026-09-27). The gate prop row itself stays unknown.
INSERT INTO stargates (address1, address2, address3, address4, address5, address6, address_origin, stargate_id, name, pitch, prefab_sequence, roll, world_id, x_pos, y_pos, yaw, z_pos, event_set_id, arrival_x, arrival_y, arrival_z, arrival_yaw) VALUES (38, 29, 27, 14, 8, 23, 15, 15, 'Agnos', 0, 'Agnos.Main_Sequence.Prefabs.GLB-Stargate_Prefab_Seq', 0, 10, 0, 0, 0, 0, 10002, 20.640, 34.939, 15.890, 0);

-- Gate 29 (Debug Area, world 1300, packet DA-07) is a Cimmeria addition: the
-- Ihpet_Crater_Light map's own gate prop, which world 1300 loads. Same
-- prefab sequence, transform, point-of-origin glyph (2) and event set (10005)
-- as gate 20, because it IS that prop on the same client map: the event set
-- resolves the gate's Kismet sequences by event id, and the client plays
-- them on whichever map is loaded, so two rows can share one set.
--
-- `debug_dial_hub = true`: outbound only. Nobody can dial it, it never
-- enters an address book, and a GM who opens its DHD can dial every other gate this
-- server can enter (column comment in Worlds/Tables/stargates.sql). Its
-- 6-glyph address 38-37-36-35-34-33 is real only so the cooked entry the
-- client is sent (`cimmeria_resources::base::stargate_overrides`) collides
-- with no shipped address; no player can hold it.
--
-- Nobody arrives through this gate (it cannot be dialled), so its arrival
-- pin only places `.gotolocation DebugArea` with no coordinates, which uses
-- a world's stargate arrival as its entry point. Pinned to the Z1 arrival
-- (respawner 130, docs/analysis/debug-area/README.md), 28 m out in front
-- of the gate and facing away from it (yaw 0 = +Z), rather than on the
-- prop's origin inside the gate's own REGION_FLAG_Stargate volume.
INSERT INTO stargates (address1, address2, address3, address4, address5, address6, address_origin, stargate_id, name, pitch, prefab_sequence, roll, world_id, x_pos, y_pos, yaw, z_pos, event_set_id, debug_dial_hub, arrival_x, arrival_y, arrival_z, arrival_yaw) VALUES (38, 37, 36, 35, 34, 33, 2, 29, 'Debug Area', 0, 'Ihpet_Crater_Light.Main_Sequence.Prefabs.GLB-Stargate_Prefab_Seq', 0, 1300, 251.25, 10.606, 0, -989.78100600000005, 10005, true, 251.0, 8.0, -962.0, 0);

